import Testing
@testable import RefractArkUI
import RefractIR

@Test func arkUIEmitsReusableNativeComponents() throws {
    let module = Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Hello", body: .text(Expression(.stringLiteral("Hello")), modifiers: [], location: nil)),
    ])
    let output = try ArkUIBackend().generate(module: module)
    #expect(output == """
    // Generated by Refract; DO NOT EDIT.
    // Source: Input.swift

    @ComponentV2
    export struct Hello {
      build() {
        Text('Hello')
      }
    }

    """)
    #expect(!output.contains("@Entry"))
    #expect(output == (try ArkUIBackend().generate(module: module)))
}

@Test func arkUIEmitsViewsAndModifiers() throws {
    let module = Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Hello", body: .stack(axis: .vertical, children: [
            .text(Expression(.stringLiteral("Hello")), modifiers: [
                Modifier(name: "fontSize", arguments: [Expression(.numberLiteral("18"))]),
                Modifier(name: "foregroundColor", arguments: [Expression(.reference("theme.titleColor"))]),
                Modifier(name: "cornerRadius", arguments: [Expression(.numberLiteral("8"))]),
            ], location: nil),
            .button(label: .text(Expression(.stringLiteral("Go")), modifiers: [], location: nil),
                    action: nil, modifiers: [], location: nil),
        ], modifiers: [Modifier(name: "padding")], location: nil)),
        Screen(name: "Empty", body: .stack(axis: .depth, children: [], modifiers: [], location: nil)),
    ])
    let output = try ArkUIBackend().generate(module: module)
    #expect(output == """
    // Generated by Refract; DO NOT EDIT.
    // Source: Input.swift

    @ComponentV2
    export struct Hello {
      build() {
        Column() {
          Text('Hello').fontSize(18).fontColor(this.theme.titleColor).borderRadius(8)
          Button() {
            Text('Go')
          }
        }.padding(0)
      }
    }

    @ComponentV2
    export struct Empty {
      build() {
        Stack() {
        }
      }
    }

    """)
    #expect(!output.contains("@Entry"))
    #expect(!output.contains("RefractRuntime"))
    #expect(output == (try ArkUIBackend().generate(module: module)))
}

@Test func arkUIEmitsConditionalBuildersAndModifiers() throws {
    let module = Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Rows", body: .stack(axis: .horizontal, children: [
            .conditional(conditions: [
                .init(condition: Expression(.boolLiteral(true)), children: [
                    .text(Expression(.stringLiteral("On")), modifiers: [], location: nil),
                ]),
                .init(condition: Expression(.reference("model.loaded")), children: [
                    .text(Expression(.stringLiteral("Loaded")), modifiers: [], location: nil),
                ]),
                .init(condition: nil, children: [
                    .text(Expression(.stringLiteral("Off")), modifiers: [
                        Modifier(name: "opacity", arguments: [Expression(.numberLiteral("0.5"))]),
                    ], location: nil),
                ]),
            ], location: nil),
        ], modifiers: [], location: nil)),
    ])
    let output = try ArkUIBackend().generate(module: module)
    #expect(output.contains("Row() {"))
    #expect(output.contains("if (true) {"))
    #expect(output.contains("} else if (this.model.loaded) {"))
    #expect(output.contains("} else {"))
    #expect(output.contains("Text('Off').opacity(0.5)"))
}

@Test func arkUIEscapesTextAndRejectsInvalidInput() throws {
    let escaped = try ArkUIBackend().generate(module: Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Escaped", body: .text(Expression(.stringLiteral("a\"b\\c\n$home")), modifiers: [], location: nil)),
    ]))
    #expect(escaped.contains("Text('a\"b\\\\c\\n\\$home')"))

    let location = SourceLocation(file: "Input.swift", line: 7, column: 3)
    let unsupported = Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Native", body: .native(NativeComponent(name: "Map"), location: location)),
    ])
    #expect(throws: Diagnostic.self) { try ArkUIBackend().generate(module: unsupported) }

    let invalid = Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Broken", body: .text(Expression(.numberLiteral("not-a-number"), location: location),
                                             modifiers: [], location: nil)),
    ])
    #expect(throws: Diagnostic.self) { try ArkUIBackend().generate(module: invalid) }
}

@Test func arkUIRejectsUnsupportedModifiersAndStringResources() throws {
    let modifier = Modifier(name: "shadow", arguments: [], location: SourceLocation(file: "Input.swift", line: 4, column: 1))
    let module = Module(sourceFile: "Input.swift", screens: [
        Screen(name: "Unsupported", body: .text(Expression(.stringKey("title")), modifiers: [modifier], location: nil)),
    ])
    #expect(throws: Diagnostic.self) { try ArkUIBackend().generate(module: module) }
}
